// Self-test: inflate, embed registry, rendering, and the ImGui texture lifecycle
// (headless ImGui context + a fake renderer backend). Exit code 0 = OK.
#include "tgs/tgs.h"
#include "tgs/tgs_embed.h"
#include "tgs/tgs_imgui.h"
#include "tgs_inflate.h"
#include "tgs_assets.h" // generated by tgs_embed()

#if TGS_IMGUI_HAS_TEXTURES
#include "imgui_internal.h"
#endif

#include <cstdio>
#include <cstring>
#include <set>
#include <string>
#include <vector>

static int g_fail = 0;
#define CHECK(cond)                                                               \
    do                                                                            \
    {                                                                             \
        if (!(cond))                                                              \
        {                                                                         \
            std::printf("  FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);         \
            ++g_fail;                                                             \
        }                                                                         \
    } while (0)

// ---------------------------------------------------------------------------
static void TestDecompress()
{
    std::printf("[decompress]\n");
    const tgs::EmbeddedAsset* a = tgs::FindEmbedded(tgs_assets::star_spin);
    CHECK(a != nullptr);
    if (!a)
        return;
    std::string json, err;
    CHECK(tgs::IsGzip(a->data, a->size));
    CHECK(tgs::Decompress(a->data, a->size, json, &err));
    CHECK(!json.empty() && json[0] == '{');
    CHECK(json.find("\"tgs\":1") != std::string::npos);

    // plain JSON passes through
    std::string json2;
    CHECK(tgs::Decompress(json.data(), json.size(), json2) && json2 == json);

    // corrupted payload -> CRC / deflate error, never silent garbage
    std::vector<unsigned char> bad(a->data, a->data + a->size);
    bad[bad.size() / 2] ^= 0x40;
    CHECK(!tgs::Decompress(bad.data(), bad.size(), json2, &err));
    std::printf("  corrupted -> \"%s\"\n", err.c_str());

    // truncated
    CHECK(!tgs::Decompress(a->data, a->size / 2, json2, &err));

    // output limit (gzip bomb protection)
    CHECK(!tgs::Decompress(a->data, a->size, json2, &err, 100));
    std::printf("  limit -> \"%s\"\n", err.c_str());

    // garbage
    const char junk[] = "not a sticker";
    CHECK(!tgs::Decompress(junk, sizeof(junk), json2, &err));

    // stored-block deflate stream built by hand: "hello"
    const unsigned char stored[] = {0x01, 0x05, 0x00, 0xFA, 0xFF, 'h', 'e', 'l', 'l', 'o'};
    std::string out;
    size_t used = 0;
    CHECK(tgs::detail::InflateRaw(stored, sizeof(stored), out, 1 << 20, &used, nullptr) == tgs::detail::InflateStatus::Ok);
    CHECK(out == "hello" && used == sizeof(stored));
    CHECK(tgs::detail::Crc32(reinterpret_cast<const uint8_t*>("123456789"), 9) == 0xCBF43926u);
    CHECK(tgs::detail::Adler32(reinterpret_cast<const uint8_t*>("Wikipedia"), 9) == 0x11E60398u);
}

static void TestRegistry()
{
    std::printf("[registry]\n");
    CHECK(tgs_assets::count >= 5);
    CHECK(tgs::EmbeddedCount() == size_t(tgs_assets::count));
    for (int i = 0; i < tgs_assets::count; ++i)
        CHECK(tgs::FindEmbedded(tgs_assets::all[i]) != nullptr);
    CHECK(tgs::FindEmbedded("nope") == nullptr);
    TGS_REGISTER_ASSETS(); // idempotent
    CHECK(tgs::EmbeddedCount() == size_t(tgs_assets::count));
    for (size_t i = 0; i + 1 < tgs::EmbeddedCount(); ++i)
        CHECK(std::strcmp(tgs::EmbeddedAt(i)->name, tgs::EmbeddedAt(i + 1)->name) < 0);
}

static void TestRender()
{
    std::printf("[render]\n");
    std::string err;
    auto anim = tgs::Animation::FromEmbedded(tgs_assets::heart_beat, &err);
    CHECK(anim != nullptr);
    if (!anim)
        return;
    CHECK(anim == tgs::Animation::FromEmbedded(tgs_assets::heart_beat)); // cached
    const auto& in = anim->Info();
    std::printf("  heart_beat: %dx%d  %.0f fps  %d frames  %.2f s\n", in.width, in.height, in.fps, in.frame_count, in.duration);
    CHECK(in.width == 512 && in.height == 512);
    CHECK(in.fps == 60.0 && in.frame_count == 120);

    const int S = 96;
    tgs::Renderer r(anim, S, S);
    CHECK(r.Valid());
    std::vector<uint8_t> rgba(S * S * 4), bgra(S * S * 4), pre(S * S * 4);
    CHECK(r.Render(10, rgba.data(), S * 4, tgs::PixelFormat::RGBA8));
    CHECK(r.Render(10, bgra.data(), S * 4, tgs::PixelFormat::BGRA8));
    CHECK(r.Render(10, pre.data(), S * 4, tgs::PixelFormat::PremulBGRA8));
    int opaque = 0, transparent = 0, mismatch = 0;
    for (int i = 0; i < S * S; ++i)
    {
        const uint8_t* p = &rgba[i * 4];
        const uint8_t* q = &bgra[i * 4];
        const uint8_t* m = &pre[i * 4];
        if (p[0] != q[2] || p[1] != q[1] || p[2] != q[0] || p[3] != q[3])
            ++mismatch;
        if (p[3] == 255)
        {
            ++opaque;
            if (p[0] != m[2] || p[2] != m[0])
                ++mismatch;
        }
        if (p[3] == 0)
            ++transparent;
    }
    std::printf("  opaque=%d transparent=%d mismatch=%d\n", opaque, transparent, mismatch);
    CHECK(opaque > 1000 && transparent > 1000 && mismatch == 0);
    // center of the heart is red
    const uint8_t* c = &rgba[((S / 2) * S + S / 2) * 4];
    CHECK(c[0] > 200 && c[1] < 120 && c[3] == 255);

    // frames differ over time; out-of-range frames are clamped
    std::vector<uint8_t> f0(S * S * 4), f1(S * S * 4);
    r.Render(0, f0.data(), S * 4);
    r.Render(10, f1.data(), S * 4);
    CHECK(f0 != f1);
    CHECK(r.Render(100000, f1.data(), S * 4));
    CHECK(r.Render(-5, f1.data(), S * 4));

    // every sample sticker loads and renders
    for (int i = 0; i < tgs_assets::count; ++i)
    {
        auto a = tgs::Animation::FromEmbedded(tgs_assets::all[i]);
        CHECK(a != nullptr);
        if (a)
        {
            tgs::Renderer rr(a, 64, 64);
            std::vector<uint8_t> px(64 * 64 * 4);
            CHECK(rr.Render(a->Info().frame_count / 2, px.data(), 64 * 4));
            int vis = 0;
            for (int k = 0; k < 64 * 64; ++k)
                vis += px[k * 4 + 3] > 0;
            CHECK(vis > 50);
        }
    }
    CHECK(!tgs::Animation::FromJson("{\"broken\":", &err));
    CHECK(!tgs::Animation::FromFile("/definitely/not/here.tgs", &err));
}

// ---------------------------------------------------------------------------
// Headless ImGui + fake renderer
// ---------------------------------------------------------------------------
static int g_created = 0, g_destroyed = 0, g_updates = 0;
static std::set<const void*> g_live;

#if TGS_IMGUI_HAS_TEXTURES
static void FakeRender(ImDrawData* dd)
{
    static int next_id = 100;
    if (!dd->Textures)
        return;
    for (ImTextureData* t : *dd->Textures)
    {
        const bool ours = t->UseColors && t->Format == ImTextureFormat_RGBA32;
        switch (t->Status)
        {
        case ImTextureStatus_WantCreate:
            t->SetTexID((ImTextureID)(intptr_t)(next_id++));
            t->BackendUserData = t;
            t->SetStatus(ImTextureStatus_OK);
            if (ours) { ++g_created; g_live.insert(t); }
            break;
        case ImTextureStatus_WantUpdates:
            CHECK(!t->Updates.empty());
            t->SetStatus(ImTextureStatus_OK);
            if (ours) ++g_updates;
            break;
        case ImTextureStatus_WantDestroy:
            if (t->UnusedFrames > 0)
            {
                t->SetTexID(ImTextureID_Invalid);
                t->BackendUserData = nullptr;
                t->SetStatus(ImTextureStatus_Destroyed);
                if (ours) { ++g_destroyed; g_live.erase(t); }
            }
            break;
        default: break;
        }
    }
    // every texture referenced by a draw command must be alive
    for (int n = 0; n < dd->CmdListsCount; ++n)
        for (const ImDrawCmd& cmd : dd->CmdLists[n]->CmdBuffer)
            if (cmd.TexRef._TexData)
                CHECK(cmd.TexRef._TexData->Status != ImTextureStatus_Destroyed);
}
static void FakeShutdown()
{
    for (ImTextureData* t : ImGui::GetPlatformIO().Textures)
        if (t->RefCount == 1 && t->TexID != ImTextureID_Invalid)
        {
            const bool ours = t->UseColors && t->Format == ImTextureFormat_RGBA32;
            t->SetTexID(ImTextureID_Invalid);
            t->BackendUserData = nullptr;
            t->SetStatus(ImTextureStatus_Destroyed);
            if (ours) { ++g_destroyed; g_live.erase(t); }
        }
}
#endif

// callbacks backend
static int cb_created = 0, cb_destroyed = 0, cb_updates = 0;
static std::set<uint64_t> cb_live;
static uint64_t CbCreate(void*, int w, int h)
{
    static uint64_t id = 1000;
    CHECK(w > 0 && h > 0);
    ++cb_created;
    cb_live.insert(++id);
    return id;
}
static bool CbUpdate(void*, uint64_t t, const void* px, int w, int h, int pitch)
{
    CHECK(cb_live.count(t) == 1);
    CHECK(px != nullptr && pitch == w * 4 && h > 0);
    ++cb_updates;
    return true;
}
static void CbDestroy(void*, uint64_t t)
{
    CHECK(cb_live.erase(t) == 1);
    ++cb_destroyed;
}

static void Frame(void (*ui)(int), int i)
{
    ImGuiIO& io = ImGui::GetIO();
    io.DisplaySize = ImVec2(1280, 720);
    io.DeltaTime = 1.0f / 60.0f;
    ImGui::NewFrame();
    ImGui::SetNextWindowPos(ImVec2(0, 0));
    ImGui::SetNextWindowSize(ImVec2(1200, 700));
    ImGui::Begin("test");
    ui(i);
    ImGui::End();
    ImGui::Render();
#if TGS_IMGUI_HAS_TEXTURES
    if (io.BackendFlags & ImGuiBackendFlags_RendererHasTextures)
        FakeRender(ImGui::GetDrawData());
#endif
}

static tgs::Player* g_player = nullptr;

static void UiScene(int i)
{
    float size = (i / 60) % 2 ? 96.0f : 64.0f; // forces texture re-creation every second
    for (int k = 0; k < tgs_assets::count; ++k)
    {
        if (k)
            ImGui::SameLine();
        if (i < 200 || k < 2) // after frame 200 only 2 widgets remain -> GC must free the rest
            tgs::ui::Sticker(tgs_assets::all[k], ImVec2(size, size));
    }
    tgs::ui::StickerOptions o;
    o.play_on_hover = true;
    tgs::ui::StickerButton(tgs_assets::loader_dots, ImVec2(48, 48), o);
    g_player->Draw(ImVec2(128, 128));
    g_player->DrawTo(ImGui::GetForegroundDrawList(), ImVec2(10, 10), ImVec2(74, 74));
}

static void TestImGui()
{
    std::printf("[imgui %s]\n", IMGUI_VERSION);
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
#if TGS_IMGUI_HAS_TEXTURES
    io.BackendFlags |= ImGuiBackendFlags_RendererHasTextures;
    io.BackendRendererName = "fake";
#else
    unsigned char* px;
    int w, h;
    io.Fonts->GetTexDataAsRGBA32(&px, &w, &h);
    io.Fonts->SetTexID((ImTextureID)(intptr_t)1);
#endif
    tgs::SetStickerCacheLifetime(30);

    tgs::PlayerOptions po;
    po.cache_frames = true;
    po.auto_update = true;
    tgs::Player player(tgs::Animation::FromEmbedded(tgs_assets::orb_ring), po);
    g_player = &player;

#if TGS_IMGUI_HAS_TEXTURES
    // ---- mode 1: ImGui-managed textures
    CHECK(tgs::GetTextureMode() == tgs::TextureMode::ImGuiManaged);
    for (int i = 0; i < 300; ++i)
        Frame(UiScene, i);
    tgs::Stats s = tgs::GetStats();
    std::printf("  managed: created=%d destroyed=%d updates=%d live=%zu | stats textures=%d dying=%d widgets=%d cache=%zu KB\n",
                g_created, g_destroyed, g_updates, g_live.size(), s.textures, s.textures_dying, s.cached_widgets,
                s.frame_cache_bytes / 1024);
    CHECK(g_created > 10 && g_updates > 100);
    CHECK(s.cached_widgets == 3);          // 2 stickers + 1 button survive GC
    CHECK(s.textures == 4);                // + explicit player (one draw size... DrawTo shares the texture? see below)
    CHECK(int(g_live.size()) <= s.textures + s.textures_dying);
    CHECK(s.frame_cache_bytes > 0);
    CHECK(player.GetFrame() > 0);
#endif

    // ---- mode 2: callbacks (switch at runtime: managed textures must be released)
    tgs::TextureCallbacks cb;
    cb.create = CbCreate;
    cb.update = CbUpdate;
    cb.destroy = CbDestroy;
    tgs::SetTextureCallbacks(&cb);
    CHECK(tgs::GetTextureMode() == tgs::TextureMode::Callbacks);
    for (int i = 300; i < 500; ++i)
        Frame(UiScene, i);
    std::printf("  callbacks: created=%d destroyed=%d updates=%d live=%zu\n", cb_created, cb_destroyed, cb_updates, cb_live.size());
    CHECK(cb_created > 5 && cb_updates > 50);
#if TGS_IMGUI_HAS_TEXTURES
    std::printf("  managed after switch: created=%d destroyed=%d live=%zu\n", g_created, g_destroyed, g_live.size());
    CHECK(g_live.empty()); // switching mode released every ImGui-managed texture
#endif

    // non-looping playback finishes
    tgs::Player once(tgs::Animation::FromEmbedded(tgs_assets::loader_dots));
    once.SetLoop(false);
    once.Update(10.0f);
    CHECK(once.IsFinished() && !once.IsPlaying() && once.GetFrame() == once.GetFrameCount() - 1);
    once.Play();
    CHECK(once.IsPlaying() && once.GetFrame() == 0);
    once.SetProgress(0.5f);
    CHECK(once.GetFrame() == once.GetFrameCount() / 2);
    once.SetSpeed(-1.0f);
    once.Update(0.1f);
    CHECK(once.GetFrame() < once.GetFrameCount() / 2);

    // ---- shutdown order: backend shutdown -> tgs::Shutdown -> DestroyContext
#if TGS_IMGUI_HAS_TEXTURES
    tgs::SetTextureCallbacks(nullptr);
    for (int i = 500; i < 520; ++i)
        Frame(UiScene, i);
    FakeShutdown();
#endif
    tgs::Shutdown();
    tgs::Stats s2 = tgs::GetStats();
    std::printf("  after shutdown: textures=%d dying=%d cb_live=%zu", s2.textures, s2.textures_dying, cb_live.size());
#if TGS_IMGUI_HAS_TEXTURES
    std::printf(" managed_live=%zu", g_live.size());
    CHECK(g_live.empty());
#endif
    std::printf("\n");
    CHECK(s2.textures == 0 && s2.textures_dying == 0);
    CHECK(cb_live.empty() && cb_created == cb_destroyed);
    g_player = nullptr;
    ImGui::DestroyContext();
    // player destroyed after the context: must not crash
}

int main()
{
    TestDecompress();
    TestRegistry();
    TestRender();
    TestImGui();
    std::printf(g_fail ? "\nFAILED: %d check(s)\n" : "\nALL OK\n", g_fail);
    return g_fail ? 1 : 0;
}
